CREATE TYPE "SOPStatus" AS ENUM ('DRAFT','ACTIVE','ARCHIVED'); CREATE TYPE "PolicyStatus" AS ENUM ('DRAFT','ACTIVE','ARCHIVED'); CREATE TYPE "PolicyEnforcement" AS ENUM ('ADVISORY','REQUIRE_APPROVAL','BLOCK'); CREATE TYPE "PolicyType" AS ENUM ('ACTION','SPEND','PUBLISHING','DATA_ACCESS','COMMUNICATION','CUSTOM');
CREATE TABLE "SOP" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"category" TEXT NOT NULL DEFAULT 'GENERAL',"tags" TEXT[] DEFAULT ARRAY[]::TEXT[],"appliesToRole" TEXT,"status" "SOPStatus" NOT NULL DEFAULT 'DRAFT',"activeVersionId" TEXT,"createdById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SOP_pkey" PRIMARY KEY("id"));
CREATE TABLE "SOPVersion" ("id" TEXT NOT NULL,"sopId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"version" INTEGER NOT NULL,"content" TEXT NOT NULL,"changeSummary" TEXT,"createdById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SOPVersion_pkey" PRIMARY KEY("id"));
CREATE TABLE "Policy" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"type" "PolicyType" NOT NULL DEFAULT 'CUSTOM',"status" "PolicyStatus" NOT NULL DEFAULT 'DRAFT',"enforcement" "PolicyEnforcement" NOT NULL DEFAULT 'ADVISORY',"rule" JSONB NOT NULL,"createdById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Policy_pkey" PRIMARY KEY("id"));
CREATE TABLE "TaskSOP" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"sopId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TaskSOP_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "SOP_id_projectId_key" ON "SOP"("id","projectId");CREATE INDEX "SOP_projectId_status_updatedAt_idx" ON "SOP"("projectId","status","updatedAt");CREATE UNIQUE INDEX "SOPVersion_sopId_version_key" ON "SOPVersion"("sopId","version");CREATE UNIQUE INDEX "SOPVersion_id_projectId_key" ON "SOPVersion"("id","projectId");CREATE INDEX "Policy_projectId_status_type_idx" ON "Policy"("projectId","status","type");CREATE UNIQUE INDEX "TaskSOP_taskId_sopId_key" ON "TaskSOP"("taskId","sopId");CREATE INDEX "TaskSOP_projectId_sopId_idx" ON "TaskSOP"("projectId","sopId");
ALTER TABLE "SOP" ADD CONSTRAINT "SOP_projectId_fkey" FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE;ALTER TABLE "SOPVersion" ADD CONSTRAINT "SOPVersion_sopId_projectId_fkey" FOREIGN KEY("sopId","projectId") REFERENCES "SOP"("id","projectId") ON DELETE CASCADE;ALTER TABLE "SOP" ADD CONSTRAINT "SOP_activeVersionId_projectId_fkey" FOREIGN KEY("activeVersionId","projectId") REFERENCES "SOPVersion"("id","projectId") ON DELETE RESTRICT;ALTER TABLE "Policy" ADD CONSTRAINT "Policy_projectId_fkey" FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE;ALTER TABLE "TaskSOP" ADD CONSTRAINT "TaskSOP_taskId_projectId_fkey" FOREIGN KEY("taskId","projectId") REFERENCES "Task"("id","projectId") ON DELETE CASCADE;ALTER TABLE "TaskSOP" ADD CONSTRAINT "TaskSOP_sopId_projectId_fkey" FOREIGN KEY("sopId","projectId") REFERENCES "SOP"("id","projectId") ON DELETE CASCADE;ALTER TABLE "TaskSOP" ADD CONSTRAINT "TaskSOP_projectId_fkey" FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE;
